package com.eventdrivencommerce.payment.infrastructure.messaging;
import org.apache.kafka.clients.consumer.ConsumerRecord;import org.springframework.context.annotation.*;import org.springframework.kafka.core.KafkaTemplate;import org.springframework.kafka.listener.*;import org.springframework.kafka.support.ExponentialBackOffWithMaxRetries;
@Configuration public class KafkaConfiguration{@Bean CommonErrorHandler paymentErrorHandler(KafkaTemplate<String,String> kafka){var recoverer=new DeadLetterPublishingRecoverer(kafka,(ConsumerRecord<?,?>r,Exception e)->new org.apache.kafka.common.TopicPartition(r.topic()+".dlt",r.partition()));var backoff=new ExponentialBackOffWithMaxRetries(4);backoff.setInitialInterval(250);backoff.setMultiplier(2);backoff.setMaxInterval(2000);return new DefaultErrorHandler(recoverer,backoff);}}
